      "confidence": 0.5
    },
    {
      "symbol": "A10",
      "target_weight": 0.02,
      "rationale": "Redundant with A02 within us_broad but with a wider interval (0.0559 vs 0.0389) and -4.8% 20d momentum; held near zero rather than the 6.7% baseline. Reduction is unrestricted.",
      "confidence": 0.55
    },
    {
      "symbol": "A06",
      "target_weight": 0.095,
      "rationale": "Second-tightest interval (0.0433) provides international diversification outside the US-heavy book; modest overweight vs 8.6% baseline despite -2.7% 20d, since width is the reliable signal and median direction is not.",
      "confidence": 0.5
